 "check1", "verdict": "PASS"}, "desc_sha256": "c6386889553b7460440f1f38667c95aac9966962c303dfd6884a4f10817c292f", "kind": "teaser", "lane": "WB", "run": "wb-ws-2026-09-27-02", "text_sha256": "e24b7ceb8df3c388e9f394bb2aff54357f59da7d9246ec8cd8076cfd1c747968", "v": 2, "verify": {"at": "2026-09-30T08:46:45+00:00", "by": "teaser-wb-ws-2026-09-27-02-verify-060", "claims": 4, "stage": "verify", "text_sha256": "e24b7ceb8df3c388e9f394bb2aff54357f59da7d9246ec8cd8076cfd1c747968", "unproven": 0, "verdict": "VERIFIED"}, "web_facts": []}}', '{"description_citations": [{"n": 1, "url": "https://en.wikipedia.org/w/index.php?title=Cotzumalhuapa&oldid=1356924282", "title": "Wikipedia: Cotzumalhuapa", "domain": "en.wikipedia.org", "license": "CC BY-SA 4.0"}], "_description_provenance": {"v": 1, "ai": "selected", "run": "mass-2026-09-25", "card": {"items": [{"drop": [[1047, 1059]], "sentence": 2}], "text_sha256": "3e09361584fc3727718cb5003d245e3d612928a68e3c1abf300946660905c05c"}, "lane": "W", "licence": "CC BY-SA 4.0", "sources": [{"id": "W", "url": "https://en.wikipedia.org/w/index.php?title=Cotzumalhuapa&oldid=1356924282", "revid": 1356924282, "licence": "CC BY-SA 4.0", "text_sha256": "cf650f6392f58f6fd9a2c2a953300f25d0b2944e62f93a7d0b4a420dab766eb8", "rev_timestamp": "2026-05-30T17:56:56Z"}], "ai_system": "Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09", "sentences": [{"n": 1, "end": 594, "src": "W", "drop": [], "start": 304}, {"n": 1, "end": 939, "src": "W", "drop": [], "start": 785}, {"n": 1, "end": 1060, "src": "W", "drop": [[1047, 1059]], "start": 940}], "attribution": {"url": "https://en.wikipedia.org/w/index.php?title=Cotzumalhuapa&oldid=1356924282", "title": "Cotzumalhuapa", "changes": "sentences selected and shortened", "licence_url": "https://creativecommons.org/licenses/by-sa/4.0/"}, "desc_sha256": "c6386889553b7460440f1f38667c95aac9966962c303dfd6884a4f10817c292f"}}', 'teaser-prov-s029-rollback:b3b17110-a61a-43c1-8962-